const menuGroups=[{name:'实际使用',icon:'▦',items:[0,1,2,3]},{name:'配置管理',icon:'⚙',items:[4,5]}];let menuOpen=JSON.parse(localStorage.getItem('yt-menu-open')||'[true,true]');
function toggleMenu(i){menuOpen[i]=!menuOpen[i];localStorage.setItem('yt-menu-open',JSON.stringify(menuOpen));nav()}
function goPage(i){page=i;menuOpen[i<4?0:1]=true;closeDrawer();render()}
nav=function(){document.getElementById('nav').innerHTML=menuGroups.map((g,i)=>`<section class="menugroup"><button class="menutitle ${g.items.includes(page)?'contains-active':''}" aria-expanded="${menuOpen[i]}" aria-controls="menu-group-${i}" onclick="toggleMenu(${i})"><span>${g.icon}　${g.name}</span><span class="chevron ${menuOpen[i]?'open':''}">›</span></button><div id="menu-group-${i}" ${menuOpen[i]?'':'hidden'}>${g.items.map(n=>`<button class="menusub ${page===n?'active':''}" ${page===n?'aria-current="page"':''} onclick="goPage(${n})"><span class="menudot">${['▤','↗','▧','☑','◎','⚙'][n]}</span>${pages[n]}</button>`).join('')}</div></section>`).join('')};
const menuRender=render;render=function(){menuRender();document.getElementById('crumb').textContent=(page<4?'实际使用':'配置管理')+' / '+pages[page]};
const menuStyle=document.createElement('style');menuStyle.textContent='aside nav .menutitle{display:flex;justify-content:space-between;align-items:center;color:#263c59;font-weight:600;padding:14px 15px;margin:2px 0}aside nav .menutitle:hover{background:#f5f8fc}aside nav .menutitle.contains-active{color:#1677ff}aside nav .menusub{padding:12px 14px 12px 36px;font-size:12px;margin:2px 0;display:flex;align-items:center;gap:12px;color:#576b84}aside nav .menusub:hover{background:#f2f7fe}aside nav .menusub.active{background:#e7f2ff;color:#0087ff}.menudot{font-size:12px;width:15px;color:#8c9bb0}.menusub.active .menudot{color:#168bff}.menugroup{margin-bottom:12px}.chevron{font-size:20px;transition:transform .18s;color:#9aa6b5}.chevron.open{transform:rotate(90deg)}.menugroup [hidden]{display:none!important}@media(max-width:750px){aside nav{display:block}.menugroup{margin:0}aside nav .menusub{padding-left:40px}}';document.head.append(menuStyle);render();
